head.b:skin:
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#000;font-family:Arial,Helvetica,sans-serif;color:#fff}.page{position:relative;width:100%;max-width:520px;height:100dvh;margin:auto;overflow:hidden;background:#000}video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;background:#111}.shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(0,0,0,.48),rgba(0,0,0,0) 27%,rgba(0,0,0,.03) 54%,rgba(0,0,0,.78) 100%)}
.top{position:absolute;top:10px;left:10px;right:10px;display:flex;align-items:center;gap:8px}.profile{display:flex;cursor:pointer;align-items:center;gap:8px;background:rgba(10,10,14,.72);backdrop-filter:blur(8px);padding:5px 10px 5px 5px;border-radius:28px;box-shadow:0 4px 18px #0007}.avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;font-size:22px;background:linear-gradient(135deg,#ff3d8b,#ffbf39);border:2px solid #fff}.avatar img{width:100%;height:100%;object-fit:cover;border-radius:50%;display:block}.name{font-size:14px;font-weight:800;white-space:nowrap}.meta{font-size:11px;color:#ddd;margin-top:3px}.live{display:inline-block;background:#ff2b63;padding:3px 6px;border-radius:6px;font-size:9px;font-weight:900;margin-left:4px}.follow{background:#ff4b8e;border:0;color:#fff;font-weight:800;padding:9px 13px;border-radius:22px;font-size:12px;box-shadow:0 3px 10px #0005}.close{margin-left:auto;width:36px;height:36px;border:0;border-radius:50%;background:#0008;color:#fff;font-size:22px}
.roomStats{position:absolute;top:66px;left:10px;display:flex;gap:7px}.pill{background:#0009;border:1px solid #ffffff22;border-radius:18px;padding:7px 10px;font-size:11px;font-weight:700;backdrop-filter:blur(7px)}.pill.gold{color:#ffd84d}.pill.pink{color:#ff9bd0}
.rank{position:absolute;right:10px;top:69px;background:linear-gradient(90deg,#ff2b67dd,#a92effd9);padding:6px 11px;border-radius:16px;font-size:11px;font-weight:900;box-shadow:0 5px 18px #0006}.rank span{opacity:.75;font-weight:600}
.topgifts{position:absolute;right:10px;top:102px;width:168px;background:#0b0b10b8;border:1px solid #ffffff18;border-radius:14px;padding:8px 10px;backdrop-filter:blur(10px)}.topgifts .title{font-size:10px;color:#bbb;margin-bottom:5px}.grow{display:flex;align-items:center;gap:6px;padding:3px 0;font-size:11px}.grow .mini{width:23px;height:23px;border-radius:50%;display:grid;place-items:center;background:#ffffff14}.grow b{margin-left:auto;color:#ffd44b}
.giftAlert{position:absolute;left:10px;top:39%;min-width:245px;max-width:78%;padding:7px 10px 7px 7px;display:flex;align-items:center;gap:8px;background:linear-gradient(90deg,rgba(38,10,42,.94),rgba(9,9,15,.83));border:1px solid rgba(255,255,255,.14);border-radius:13px;box-shadow:0 8px 30px #0009;opacity:0;transform:translateX(-30px) scale(.92);pointer-events:none}.giftAlert.show{animation:giftIn 4.1s cubic-bezier(.18,.8,.25,1) forwards}.giftImg{width:58px;height:58px;object-fit:contain;filter:drop-shadow(0 0 9px #ff4e9c)}.giftFallback{width:58px;height:58px;display:grid;place-items:center;font-size:43px}.gbody{min-width:0}.giver{font-size:13px;font-weight:900}.lv{font-size:9px;background:#ff3b78;padding:3px 5px;border-radius:5px;margin-left:3px}.gtext{font-size:11px;color:#ddd;margin-top:2px}.gcount{margin-left:auto;font-size:27px;font-weight:1000;font-style:italic;color:#ffd34e;text-shadow:0 2px 0 #6e3b00;white-space:nowrap}@keyframes giftIn{0%{opacity:0;transform:translateX(-30px) scale(.92)}10%{opacity:1;transform:translateX(0) scale(1)}18%{transform:translateX(4px) scale(1.03)}24%{transform:translateX(0) scale(1)}78%{opacity:1;transform:translateX(0)}100%{opacity:0;transform:translateX(-18px) scale(.98)}}
.bigGift{position:absolute;left:50%;top:47%;transform:translate(-50%,-50%) scale(.2);font-size:105px;opacity:0;pointer-events:none;text-align:center;text-shadow:0 0 22px #fff,0 0 45px #ff4d9e}.bigGift.show{animation:bigGift 2.9s ease forwards}@keyframes bigGift{0%{opacity:0;transform:translate(-50%,-50%) scale(.2) rotate(-12deg)}12%{opacity:1;transform:translate(-50%,-50%) scale(1.18) rotate(5deg)}24%{transform:translate(-50%,-50%) scale(.95) rotate(-3deg)}42%{transform:translate(-50%,-50%) scale(1)}82%{opacity:1;transform:translate(-50%,-54%) scale(1.04)}100%{opacity:0;transform:translate(-50%,-70%) scale(1.35)}}
.float{position:absolute;right:26px;bottom:170px;font-size:27px;opacity:0;pointer-events:none}.float.show{animation:floatUp 2.8s ease forwards}@keyframes floatUp{0%{opacity:0;transform:translateY(10px) scale(.7)}15%{opacity:1}100%{opacity:0;transform:translateY(-220px) translateX(-15px) scale(1.2)}}
.chat{position:absolute;left:10px;right:70px;bottom:128px;display:flex;flex-direction:column;gap:5px}.msg{width:max-content;max-width:100%;background:rgba(0,0,0,.52);border-radius:15px;padding:6px 9px;font-size:12px;line-height:1.2;opacity:0;transform:translateX(-18px)}.msg.show{animation:chatIn .38s ease forwards}@keyframes chatIn{to{opacity:1;transform:translateX(0)}}.msg b{color:#ffacd3}.msg .heart{color:#ff5c8d}
.hearts{position:absolute;right:10px;bottom:116px;display:flex;flex-direction:column;align-items:center;gap:5px}.heart{font-size:25px;opacity:0}.heart.go{animation:heartUp 2.4s ease forwards}@keyframes heartUp{0%{opacity:0;transform:translateY(15px) scale(.6)}15%{opacity:1}100%{opacity:0;transform:translateY(-180px) translateX(-15px) scale(1.25)}}
.bottom{position:absolute;left:10px;right:10px;bottom:9px}.tools{display:flex;gap:7px;align-items:center}.input{height:43px;flex:1;background:#0009;border:1px solid #ffffff1a;border-radius:24px;padding:0 13px;display:flex;align-items:center;color:#aaa;font-size:12px}.tool{width:43px;height:43px;border:1px solid #ffffff15;border-radius:50%;background:#000a;color:#fff;font-size:19px}.giftBtn{background:linear-gradient(135deg,#ff3d79,#a92eff);box-shadow:0 0 15px #ff3d7955}.watch{display:block;margin:8px auto 0;max-width:285px;text-align:center;text-decoration:none;background:linear-gradient(90deg,#ff2d71,#ff3b9c);color:#fff;font-weight:900;font-size:16px;padding:12px 22px;border-radius:28px;box-shadow:0 7px 25px #ff2d714d}
.tap{position:absolute;inset:0;pointer-events:auto;background:transparent;border:0}.tapHint{position:absolute;left:50%;top:59%;transform:translate(-50%,-50%);padding:7px 12px;border-radius:18px;background:#0007;color:#fff;font-size:11px;opacity:0;pointer-events:none}.tapHint.show{animation:hint 1.5s ease}@keyframes hint{0%{opacity:0;transform:translate(-50%,-50%) scale(.8)}25%{opacity:1}100%{opacity:0;transform:translate(-50%,-80%) scale(1.05)}}
